/**
 * Product screenshots for the landing page.
 *
 * Usage:
 *   just screenshots          # English
 *   just screenshots de       # German
 *
 * Requires:
 *   - Frontend running at http://localhost:5555 with VITE_E2E_AUTH_BYPASS=true
 *   - Backend running at http://localhost:8787 with TESTING=true
 *
 * No credentials are involved. An older version drove the real login form,
 * which meant screenshots could only be regenerated by whoever held the account
 * — and when that login silently failed, it wrote captures of the login page
 * over the real screenshots. This uses the same seed-and-bypass harness the E2E
 * suite runs on, so the data on screen is deliberate rather than whatever the
 * local database happened to contain.
 *
 * Each page is captured twice, light and dark, always in the default (earthy)
 * palette, into `public/screenshots/<lang>/<name>-<mode>.png`. What the feature
 * pages and guides show is captured on a phone as well, as `<name>-phone-<mode>.png`,
 * since a visitor can choose between the two there.
 *
 * Those captures also measure the parts the text points at with numbered marks
 * (`MARKS`), and write where they are to `src/docs/captures.json`, so the
 * numbers land on the right spot again after every capture.
 */
import {
  type Browser,
  type BrowserContext,
  type ElementHandle,
  type Locator,
  type Page,
  expect,
  test,
} from '@playwright/test'
import { readFileSync, writeFileSync } from 'node:fs'

import type { Captures, MarkPlace } from '../src/lib/doc-types'
import {
  type CastMember,
  type Locale,
  type TaskSeed,
  type TeamSeed,
  WORLD,
} from './screenshots.data.js'

const BASE_URL = 'http://localhost:5555'
const API = process.env.VITE_API_URL ?? 'http://localhost:8787/api/v1'

const LANG: Locale = process.env.LANG === 'de' ? 'de' : 'en'
const SCREENSHOT_DIR = `public/screenshots/${LANG}`
const VIEWPORT = { width: 1440, height: 900 }
// Sizes in `components/landing/ScreenshotFrame.vue` follow this.
const PHONE_VIEWPORT = { width: 390, height: 844 }
const MODES = ['light', 'dark'] as const
const DEVICES = ['desktop', 'phone'] as const
type Mode = (typeof MODES)[number]
type Device = (typeof DEVICES)[number]

const CAPTURES_FILE = 'src/docs/captures.json'

/** The file a screen is saved under on a device, as `src/lib/doc-shots.ts` reads it. */
const fileOf = (name: string, device: Device) => (device === 'phone' ? `${name}-phone` : name)

const EMAIL_DOMAIN = 'example.org'
const world = WORLD[LANG]

// ── Seeding (Node side, via the TESTING-only endpoints) ──────────────────────

const addressOf = (handle: string) => `${handle}@${EMAIL_DOMAIN}`

async function apiAs<T>(method: string, path: string, email: string, body?: object): Promise<T> {
  const res = await fetch(`${API}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json', 'X-Test-User-Email': email },
    body: body ? JSON.stringify(body) : undefined,
  })
  if (!res.ok) {
    throw new Error(`API ${method} ${path} failed: ${res.status} ${await res.text()}`)
  }
  return res.status === 204 ? (null as T) : ((await res.json()) as T)
}

async function seedUser(handle: string, name: string): Promise<void> {
  const res = await fetch(`${API}/testing/seed`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      email: addressOf(handle),
      name,
      roles: [],
      is_active: true,
      preferred_language: LANG,
    }),
  })
  if (!res.ok) throw new Error(`Seeding ${handle} failed: ${res.status} ${await res.text()}`)
}

/** ISO date `offset` days from today. */
function isoDate(offset: number): string {
  const d = new Date()
  d.setDate(d.getDate() + offset)
  return d.toISOString().slice(0, 10)
}

/**
 * The festival starts tomorrow and runs five days.
 *
 * Every shift stays in the future — the backend filters past ones away — while
 * still falling inside the week-from-today strip the task list renders, so the
 * roster shows real occupancy instead of a row of em dashes.
 */
const EVENT_START_OFFSET = 1
const EVENT_DAYS = 5

/**
 * How many shifts the organiser takes on herself.
 *
 * The dashboard leads with "your next shift", so an organiser who has booked
 * nothing captures an empty state — accurate, but a poor description of the
 * screen. Somebody who both runs an event and helps at it is the ordinary
 * case, and three shifts across three jobs is what that looks like.
 */
const ORGANISER_SHIFTS = 3

interface SeededTask {
  seed: TaskSeed
  id: string
}

interface SeededWorld {
  organiserEmail: string
  eventId: string
  tasks: SeededTask[]
  /** Task the `task-detail` capture opens, which runs a stand that takes vouchers. */
  featuredTaskId: string
  /** A shift of the featured task, for the shift dialog. */
  featuredShiftId: string
}

async function seedWorld(): Promise<SeededWorld> {
  // Only removes users whose subject starts with `test|`, so a real local
  // account and anything it owns is left alone.
  const reset = await fetch(`${API}/testing/reset`, { method: 'POST' })
  if (!reset.ok) throw new Error(`Reset failed: ${reset.status} ${await reset.text()}`)

  await seedUser(world.organiser.handle, world.organiser.name)
  for (const volunteer of world.volunteers) {
    await seedUser(volunteer.handle, volunteer.name)
  }

  const organiserEmail = addressOf(world.organiser.handle)

  const event = await apiAs<{ id: string }>('POST', '/events/', organiserEmail, {
    name: world.event.name,
    description: world.event.description,
    status: 'published',
    visibility: 'public',
    start_date: isoDate(EVENT_START_OFFSET),
    end_date: isoDate(EVENT_START_OFFSET + EVENT_DAYS - 1),
  })

  // Everyone joins through the real invitation flow.
  for (const volunteer of world.volunteers) {
    const invitation = await apiAs<{ token: string }>(
      'POST',
      `/events/${event.id}/invitations`,
      organiserEmail,
      { email: addressOf(volunteer.handle), role: 'member' },
    )
    await apiAs('POST', `/invitations/${invitation.token}/accept`, addressOf(volunteer.handle))
  }

  await apiAs('PUT', '/users/me/selected-event', organiserEmail, { selected_event_id: event.id })

  const tasks: SeededTask[] = []
  for (const seed of world.tasks) {
    const days = [...seed.days].sort((a, b) => a - b)
    const created = await apiAs<{ task: { id: string } }>(
      'POST',
      '/tasks/with-shifts',
      organiserEmail,
      {
        name: seed.name,
        description: seed.description,
        start_date: isoDate(EVENT_START_OFFSET + days[0]),
        end_date: isoDate(EVENT_START_OFFSET + days[days.length - 1]),
        status: 'published',
        location: seed.location,
        category: seed.category,
        event_id: event.id,
        schedule: {
          default_start_time: `${seed.startTime}:00`,
          default_end_time: `${seed.endTime}:00`,
          shift_duration_minutes: seed.shiftMinutes,
          people_per_shift: seed.peoplePerShift,
          remainder_mode: 'drop',
          overrides: [],
          excluded_shifts: [],
        },
      },
    )
    tasks.push({ seed, id: created.task.id })
  }

  await fillRoster(tasks, organiserEmail)
  await bookOrganiser(tasks, organiserEmail)

  const featured = tasks.find((t) => t.seed.key === 'kitchen') ?? tasks[0]
  await seedPeopleInCharge(featured.id, organiserEmail)
  await seedVouchers(event.id, tasks, organiserEmail)
  await seedTeams(event.id, tasks, organiserEmail)

  const { items: featuredShifts } = await apiAs<{
    items: { id: string; date: string; start_time: string }[]
  }>('GET', `/shifts/?task_id=${featured.id}&limit=200`, organiserEmail)
  const [firstShift] = featuredShifts.sort((a, b) =>
    `${a.date}${a.start_time}`.localeCompare(`${b.date}${b.start_time}`),
  )

  return {
    organiserEmail,
    eventId: event.id,
    tasks,
    featuredTaskId: featured.id,
    featuredShiftId: firstShift.id,
  }
}

/** The cast member with this first name. Throws on a typo rather than capturing nobody. */
function volunteer(firstName: string): CastMember {
  const found = world.volunteers.find((v) => v.name.startsWith(firstName))
  if (!found) throw new Error(`No volunteer called ${firstName}`)
  return found
}

async function userId(handle: string): Promise<string> {
  const me = await apiAs<{ id: string }>('GET', '/users/me', addressOf(handle))
  return me.id
}

/** Two people run the featured task, and a third has an invitation they haven't answered. */
async function seedPeopleInCharge(taskId: string, organiserEmail: string): Promise<void> {
  for (const name of ['Miriam', 'Jonas']) {
    await apiAs('POST', `/tasks/${taskId}/managers`, organiserEmail, {
      user_id: await userId(volunteer(name).handle),
    })
  }
  await apiAs('POST', `/tasks/${taskId}/managers/invite`, organiserEmail, {
    email: addressOf('anna.weber'),
  })
}

/**
 * Shifts that earn vouchers, a stand that takes them, and a job already done, so
 * balances, history and worked hours have something to show. The done job's
 * shifts are booked while still ahead and then moved back, which is the only way
 * into the past: booking a shift that is over is refused.
 */
async function seedVouchers(
  eventId: string,
  tasks: SeededTask[],
  organiserEmail: string,
): Promise<void> {
  const byKey = (key: string) => tasks.find((task) => task.seed.key === key)!
  await apiAs('PATCH', `/tasks/${byKey('welcome').id}`, organiserEmail, { vouchers_per_shift: 2 })
  await apiAs('PATCH', `/tasks/${byKey('stage').id}`, organiserEmail, { vouchers_per_shift: 3 })
  await apiAs('PATCH', `/tasks/${byKey('kitchen').id}`, organiserEmail, {
    vouchers_per_shift: 2,
    is_voucher_point: true,
  })

  const prep = world.prep
  const { task } = await apiAs<{ task: { id: string } }>(
    'POST',
    '/tasks/with-shifts',
    organiserEmail,
    {
      name: prep.name,
      description: prep.description,
      start_date: isoDate(EVENT_START_OFFSET + prep.days[0]),
      end_date: isoDate(EVENT_START_OFFSET + prep.days[prep.days.length - 1]),
      status: 'published',
      location: prep.location,
      category: prep.category,
      event_id: eventId,
      schedule: {
        default_start_time: `${prep.startTime}:00`,
        default_end_time: `${prep.endTime}:00`,
        shift_duration_minutes: prep.shiftMinutes,
        people_per_shift: prep.peoplePerShift,
        remainder_mode: 'drop',
        overrides: [],
        excluded_shifts: [],
      },
    },
  )
  await apiAs('PATCH', `/tasks/${task.id}`, organiserEmail, { vouchers_per_shift: 2 })

  const { items: shifts } = await apiAs<{ items: { id: string; date: string }[] }>(
    'GET',
    `/shifts/?task_id=${task.id}&limit=200`,
    organiserEmail,
  )
  shifts.sort((a, b) => a.date.localeCompare(b.date))
  const rosters = [
    ['Hannah', 'Noah', 'Clara', 'Sofia'],
    ['Hannah', 'Elias', 'David', 'Jonas'],
  ]
  for (const [index, shift] of shifts.entries()) {
    for (const name of rosters[index] ?? []) {
      await apiAs('POST', '/bookings/', addressOf(volunteer(name).handle), { shift_id: shift.id })
    }
  }
  for (const [index, shift] of shifts.entries()) {
    await apiAs('PATCH', `/shifts/${shift.id}`, organiserEmail, {
      date: isoDate(-(shifts.length - index)),
    })
  }

  const redemptions: [string, number][] = [
    ['Hannah', 2],
    ['Noah', 1],
    ['Sofia', 2],
    ['David', 1],
  ]
  for (const [name, amount] of redemptions) {
    await apiAs('POST', `/events/${eventId}/vouchers/redeem`, organiserEmail, {
      task_id: byKey('kitchen').id,
      user_id: await userId(volunteer(name).handle),
      amount,
      request_id: crypto.randomUUID(),
    })
  }
  await apiAs('POST', `/events/${eventId}/vouchers/adjustments`, organiserEmail, {
    user_id: await userId(volunteer('Hannah').handle),
    amount: 1,
    note: world.correctionNote,
  })
}

/** A team with checks and two requests waiting, and an open team people simply joined. */
async function seedTeams(
  eventId: string,
  tasks: SeededTask[],
  organiserEmail: string,
): Promise<void> {
  const [checked, open] = world.teams
  const create = (team: TeamSeed) =>
    apiAs<{ id: string }>('POST', `/events/${eventId}/teams`, organiserEmail, {
      name: team.name,
      description: team.description,
      requires_approval: team.requiresApproval,
      requirements: team.requirements.map((item) => ({
        label: item.label,
        ask_issue_date: item.askIssueDate,
        valid_for_years: item.validForYears,
      })),
    })

  const checkedTeam = await create(checked)
  for (const name of ['Miriam', 'Noah']) {
    await apiAs(
      'POST',
      `/events/${eventId}/teams/${checkedTeam.id}/join`,
      addressOf(volunteer(name).handle),
      {
        message: checked.joinMessage,
      },
    )
  }
  const kids = tasks.find((task) => task.seed.key === 'kids')!
  await apiAs('PATCH', `/tasks/${kids.id}`, organiserEmail, { team_id: checkedTeam.id })

  const openTeam = await create(open)
  for (const name of ['David', 'Sofia', 'Elias']) {
    await apiAs(
      'POST',
      `/events/${eventId}/teams/${openTeam.id}/join`,
      addressOf(volunteer(name).handle),
      {},
    )
  }
}

/**
 * Book shifts so the roster looks lived-in.
 *
 * Volunteers are handed out round-robin and never booked onto two overlapping
 * shifts, because the backend rejects overlaps and the resulting error would
 * leave the roster half-filled in a way that differs between runs.
 */
async function fillRoster(tasks: SeededTask[], organiserEmail: string): Promise<void> {
  const busy = new Map<string, { start: number; end: number }[]>()
  const bookings: { email: string; shiftId: string }[] = []
  let nextVolunteer = 0

  const overlaps = (email: string, start: number, end: number) =>
    (busy.get(email) ?? []).some((slot) => start < slot.end && end > slot.start)

  for (const task of tasks) {
    const { items: shifts } = await apiAs<{
      items: { id: string; start_time: string; end_time: string }[]
    }>('GET', `/shifts/?task_id=${task.id}&limit=200`, organiserEmail)

    shifts.sort((a, b) => a.start_time.localeCompare(b.start_time))

    shifts.forEach((shift, index) => {
      const fraction = task.seed.fillPattern[index % task.seed.fillPattern.length]
      const wanted = Math.round(task.seed.peoplePerShift * fraction)
      const start = Date.parse(shift.start_time)
      const end = Date.parse(shift.end_time)

      const takenHere: string[] = []
      let attempts = 0
      while (takenHere.length < wanted && attempts < world.volunteers.length * 2) {
        const candidate = addressOf(
          world.volunteers[nextVolunteer % world.volunteers.length].handle,
        )
        nextVolunteer += 1
        attempts += 1
        if (takenHere.includes(candidate) || overlaps(candidate, start, end)) continue
        takenHere.push(candidate)
        busy.set(candidate, [...(busy.get(candidate) ?? []), { start, end }])
      }

      bookings.push(...takenHere.map((email) => ({ email, shiftId: shift.id })))
    })
  }

  for (const { email, shiftId } of bookings) {
    // A rejected booking is not worth failing the whole capture over; that
    // shift simply stays emptier than intended.
    await apiAs('POST', '/bookings/', email, { shift_id: shiftId }).catch(() => undefined)
  }

  console.log(`  booked ${bookings.length} places`)
}

/**
 * Put the organiser on a handful of shifts of her own, one per job.
 *
 * Runs after `fillRoster`, so it can only take places the volunteers left, and
 * it re-reads occupancy rather than assuming any: a job whose shifts all
 * filled up is skipped instead of collecting 409s.
 */
async function bookOrganiser(tasks: SeededTask[], organiserEmail: string): Promise<void> {
  interface ShiftRow {
    id: string
    date: string
    start_time: string
    end_time: string
    current_bookings: number
    max_bookings: number
  }

  const mine: { start: number; end: number }[] = []
  let booked = 0

  for (const task of tasks) {
    if (booked >= ORGANISER_SHIFTS) break

    const { items } = await apiAs<{ items: ShiftRow[] }>(
      'GET',
      `/shifts/?task_id=${task.id}&limit=200`,
      organiserEmail,
    )
    const open = items
      .filter((shift) => shift.current_bookings < shift.max_bookings)
      .sort((a, b) => `${a.date}${a.start_time}`.localeCompare(`${b.date}${b.start_time}`))

    for (const shift of open) {
      const start = Date.parse(`${shift.date}T${shift.start_time}`)
      const end = Date.parse(`${shift.date}T${shift.end_time}`)
      if (mine.some((slot) => start < slot.end && end > slot.start)) continue
      const accepted = await apiAs('POST', '/bookings/', organiserEmail, { shift_id: shift.id })
        .then(() => true)
        .catch(() => false)
      if (!accepted) continue
      mine.push({ start, end })
      booked += 1
      break
    }
  }

  console.log(`  organiser is on ${booked} shifts herself`)
}

// ── Browser setup ────────────────────────────────────────────────────────────

/**
 * A context authenticated as the organiser, pinned to one locale and colour
 * mode, with the cookie banner and "what's new" dialog pre-dismissed so neither
 * lands in a capture.
 */
async function openContext(
  browser: Browser,
  email: string,
  mode: (typeof MODES)[number],
  { name = world.organiser.name, phone = false }: { name?: string; phone?: boolean } = {},
): Promise<{ context: BrowserContext; page: Page }> {
  const context = await browser.newContext(
    phone ? { viewport: PHONE_VIEWPORT, deviceScaleFactor: 2 } : { viewport: VIEWPORT },
  )
  await context.addCookies([{ name: 'e2e_bypass', value: '1', domain: 'localhost', path: '/' }])

  await context.addInitScript(
    (setup: { email: string; name: string; lang: string; mode: string }) => {
      // Who the SPA believes it is. `src/testing/fake-session.ts` reads this and
      // installs a session from it without a password or a round trip; the
      // *server* is convinced separately, by the header injected below. The two
      // have to name the same address.
      localStorage.setItem(
        'wirksam-e2e-user',
        JSON.stringify({ email: setup.email, name: setup.name }),
      )
      localStorage.setItem('locale', setup.lang)
      // Screenshots always show the shipped default palette, never Classic.
      localStorage.setItem('wirksam-palette', 'default')
      localStorage.setItem('vueuse-color-scheme', setup.mode)
      localStorage.setItem('wirksam-cookie-notice-dismissed', '1')
      localStorage.setItem('wirksam-last-seen-changelog', '99.99.99')
    },
    { email, name, lang: LANG, mode },
  )

  const page = await context.newPage()
  // A selector that never resolves used to consume the entire test budget and
  // cost every capture queued behind it. Fail fast instead.
  page.setDefaultTimeout(25_000)
  await page.route('**/api/v1/**', (route) =>
    route.continue({ headers: { ...route.request().headers(), 'x-test-user-email': email } }),
  )

  return { context, page }
}

/** How to find a part of a capture that the text points at. */
type Find = (page: Page, device: Device) => Locator
/** The parts of one screen, by the key the text uses. */
type Marks = Record<string, Find>

/** What this run took, with its marks, for `src/docs/captures.json`. */
const captured: Captures = {}

/**
 * How far a mark's number reaches from its centre, in pixels of the capture,
 * and the gap it keeps to its part: `ShotMarks.vue` draws a 1.25rem badge with
 * a ring, and a docs page shows a computer capture at about half its size and
 * a phone capture at about two thirds.
 */
const PIN = { desktop: { radius: 26, gap: 4 }, phone: { radius: 19, gap: 3 } } as const

/** Left, top, right and bottom, in pixels of the page. */
type Edges = [number, number, number, number]

/**
 * Where each mark's number goes, as a centre in pixels: the first spot beside
 * its part that covers no text, no control and no other mark. Left of the
 * part first, then off its top left corner, above it, right of it, off its top
 * right corner, inside its right end, below it. With no free spot, the one
 * that covers the least. A part something else covers, a sheet over a list
 * say, gets none. Runs in the page.
 */
function placePins({
  parts: marked,
  radius,
  gap,
}: {
  parts: { edges: Edges; element: Element }[]
  radius: number
  gap: number
}): ([number, number] | null)[] {
  const parts = marked.map(({ edges }) => edges)
  const width = window.innerWidth
  const height = window.innerHeight

  // Whether a colour hides what is behind it. Computed colours come as
  // `rgba(r, g, b, a)`, or with `/ a` in the other colour spaces.
  const opacity = (element: Element) => {
    if (['IMG', 'CANVAS', 'VIDEO'].includes(element.tagName)) return 1
    const colour = getComputedStyle(element).backgroundColor
    if (colour === 'transparent') return 0
    const slash = colour.match(/\/\s*([\d.]+)(%?)\s*\)$/)
    if (slash) return Number(slash[1]) / (slash[2] ? 100 : 1)
    const rgba = colour.match(/^rgba\(.*,\s*([\d.]+)\)$/)
    return rgba ? Number(rgba[1]) : 1
  }
  // How this point of an element shows: not at all under something solid,
  // dimmed under a dialog's backdrop, or clearly.
  const shows = (element: Element, x: number, y: number): 'clear' | 'dimmed' | false => {
    if (x < 0 || y < 0 || x >= width || y >= height) return false
    let dimmed = false
    for (const hit of document.elementsFromPoint(x, y)) {
      if (element.contains(hit) || hit.contains(element)) return dimmed ? 'dimmed' : 'clear'
      const alpha = opacity(hit)
      if (alpha >= 0.9) return false
      if (alpha >= 0.1) dimmed = true
    }
    return false
  }
  const middle = (rect: DOMRect): [number, number] => [
    Math.min(Math.max(rect.left + rect.width / 2, 0), width - 1),
    Math.min(Math.max(rect.top + rect.height / 2, 0), height - 1),
  ]
  const visible = (rect: DOMRect) =>
    rect.width >= 2 &&
    rect.height >= 2 &&
    rect.right > 0 &&
    rect.bottom > 0 &&
    rect.left < width &&
    rect.top < height

  // What a number must not cover: the text and the controls a visitor sees,
  // and whether they are dimmed.
  type Seen = { edges: Edges; dimmed: boolean }
  const texts: Seen[] = []
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT)
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    const element = node.parentElement
    if (!node.textContent?.trim() || !element) continue
    const range = document.createRange()
    range.selectNodeContents(node)
    for (const rect of range.getClientRects()) {
      const seen = visible(rect) && shows(element, ...middle(rect))
      if (seen) {
        texts.push({
          edges: [rect.left, rect.top, rect.right, rect.bottom],
          dimmed: seen === 'dimmed',
        })
      }
    }
  }
  const controls: Seen[] = []
  const selector =
    'input, textarea, select, button, img, svg, canvas, video, [role="switch"], [role="checkbox"], [role="radio"]'
  for (const element of document.querySelectorAll(selector)) {
    // A button with nothing in it is a click area, like the edge of the
    // sidebar, and paints nothing.
    const empty =
      element.tagName === 'BUTTON' &&
      !element.getAttribute('role') &&
      !element.textContent?.trim() &&
      !element.querySelector('svg, img')
    const rect = element.getBoundingClientRect()
    const seen = !empty && visible(rect) && shows(element, ...middle(rect))
    if (seen) {
      controls.push({
        edges: [rect.left, rect.top, rect.right, rect.bottom],
        dimmed: seen === 'dimmed',
      })
    }
  }

  // A part shows if one of five points across it does.
  const partShows = ({ edges: [left, top, right, bottom], element }: (typeof marked)[number]) =>
    [
      [0.5, 0.5],
      [0.25, 0.25],
      [0.75, 0.25],
      [0.25, 0.75],
      [0.75, 0.75],
    ].some(([fx, fy]) => shows(element, left + (right - left) * fx!, top + (bottom - top) * fy!))

  const covers = ([cx, cy]: [number, number], [left, top, right, bottom]: Edges) =>
    Math.hypot(cx - Math.min(Math.max(cx, left), right), cy - Math.min(Math.max(cy, top), bottom)) <
    radius
  const holds = (outer: Edges, inner: Edges) =>
    outer[0] <= inner[0] + 1 &&
    outer[1] <= inner[1] + 1 &&
    outer[2] >= inner[2] - 1 &&
    outer[3] >= inner[3] - 1
  const onScreen = ([cx, cy]: [number, number]) =>
    cx - radius >= 1 && cy - radius >= 1 && cx + radius <= width - 1 && cy + radius <= height - 1

  const pins: ([number, number] | null)[] = []
  for (const [index, part] of parts.entries()) {
    if (!partShows(marked[index]!)) {
      pins.push(null)
      continue
    }
    const [left, top, right, bottom] = part
    const line = top + Math.min((bottom - top) / 2, radius)
    const off = (radius + gap) * 0.72
    const spots: [number, number][] = [
      [left - gap - radius, line],
      [left - off, top - off],
      [left + radius, top - gap - radius],
      [right + gap + radius, line],
      [right + off, top - off],
      [right - gap - radius, line],
      [left + radius, bottom + gap + radius],
    ]
    // What covering each thing costs. The part's own text most, since that is
    // what the number points at; what a backdrop dims least. A control that
    // holds the part, the part itself say, costs nothing, as long as the
    // number covers none of its text. Another marked part counts, unless it
    // holds this one.
    const blocking = [
      ...texts.map(({ edges, dimmed }) => ({
        edges,
        weight: (holds(part, edges) ? 3 : 1) * (dimmed ? 0.3 : 1),
      })),
      ...controls
        .filter(({ edges }) => !holds(edges, part))
        .map(({ edges, dimmed }) => ({ edges, weight: dimmed ? 0.3 : 1 })),
      ...parts
        .filter((other) => other !== part && !holds(other, part))
        .map((edges) => ({ edges, weight: 1 })),
    ]
    const placed = pins.filter((pin): pin is [number, number] => pin !== null)
    const cost = (spot: [number, number]) =>
      blocking.reduce((sum, { edges, weight }) => sum + (covers(spot, edges) ? weight : 0), 0) +
      placed.filter(([x, y]) => Math.hypot(spot[0] - x, spot[1] - y) < radius * 2 + 2).length * 10
    const free = spots.find((spot) => onScreen(spot) && cost(spot) === 0)
    pins.push(
      free ??
        spots
          .map((spot): [number, number] => [
            Math.min(Math.max(spot[0], radius + 1), width - radius - 1),
            Math.min(Math.max(spot[1], radius + 1), height - radius - 1),
          ])
          .reduce((best, spot) => (cost(spot) < cost(best) ? spot : best)),
    )
  }
  return pins
}

/**
 * Where each marked part is, as shares of the capture, clipped to it, and
 * where its number goes. A part that is missing or off screen is left out and
 * said so, rather than failing the run: the docs test then names the mark no
 * screenshot shows.
 */
async function measure(
  page: Page,
  file: string,
  marks: Marks,
  device: Device,
): Promise<Record<string, MarkPlace>> {
  const { width, height } = page.viewportSize()!
  const parts: { key: string; edges: Edges; element: ElementHandle<Element> }[] = []
  for (const [key, find] of Object.entries(marks)) {
    const part = find(page, device).filter({ visible: true }).first()
    const box = await part.boundingBox({ timeout: 3_000 }).catch(() => null)
    const left = Math.max(box?.x ?? 0, 0)
    const top = Math.max(box?.y ?? 0, 0)
    const right = Math.min((box?.x ?? 0) + (box?.width ?? 0), width)
    const bottom = Math.min((box?.y ?? 0) + (box?.height ?? 0), height)
    if (!box || right - left < 4 || bottom - top < 4) {
      console.log(`  ! ${file}: no ${key} on screen`)
      continue
    }
    parts.push({ key, edges: [left, top, right, bottom], element: await part.elementHandle() })
  }

  const pins = parts.length
    ? await page.evaluate(placePins, {
        parts: parts.map(({ edges, element }) => ({ edges, element })),
        ...PIN[device],
      })
    : []
  const share = (value: number, of: number) => Math.round((value / of) * 10_000) / 10_000
  const places: Record<string, MarkPlace> = {}
  for (const [index, { key, edges }] of parts.entries()) {
    const pin = pins[index]
    if (!pin) {
      console.log(`  ! ${file}: ${key} is covered`)
      continue
    }
    const [left, top, right, bottom] = edges
    places[key] = {
      box: [
        share(left, width),
        share(top, height),
        share(right - left, width),
        share(bottom - top, height),
      ],
      pin: [share(pin[0], width), share(pin[1], height)],
    }
  }
  return places
}

/** Keep this language's captures and marks, beside those of the other. */
function writeCaptures(): void {
  const all = JSON.parse(readFileSync(CAPTURES_FILE, 'utf-8')) as Record<string, Captures>
  const sorted = Object.fromEntries(
    Object.keys(captured)
      .sort()
      .map((name) => [name, captured[name]!]),
  )
  all[LANG] = sorted
  writeFileSync(CAPTURES_FILE, `${JSON.stringify(all, null, 2)}\n`)
  console.log(`  wrote ${CAPTURES_FILE}`)
}

/** Save what is on screen as `name` on this device, and measure the parts `MARKS` names. */
async function capture(
  page: Page,
  name: string,
  mode: Mode,
  device: Device = 'desktop',
): Promise<void> {
  const file = fileOf(name, device)
  // Let data fetches and transitions settle. `networkidle` is unusable here —
  // Vite's HMR socket keeps the connection busy and would burn the timeout.
  await page.waitForTimeout(900)
  // Loading placeholders pulse. Wait them out, so no capture shows a skeleton.
  await page
    .waitForFunction(() => document.querySelectorAll('.animate-pulse').length === 0, null, {
      timeout: 15_000,
    })
    .catch(() => console.log(`  still loading: ${name}`))
  // The dev server injects Vue DevTools' floating button; it is not the app.
  await page.addStyleTag({
    content: '#__vue-devtools-container__, #vue-inspector-container { display: none !important; }',
  })
  const path = `${SCREENSHOT_DIR}/${file}-${mode}.png`
  const image = await page.screenshot({ type: 'png' })
  // A blank page compresses to a few kilobytes, a screen of the app to many
  // times that. It happens when the dev server reloads the page mid-run, after
  // an edit to the source, and a retry would show the page without what this
  // capture opened on it.
  if (image.length < 20_000) {
    throw new Error(`${path} came out blank: did the dev server reload the page?`)
  }
  await save(path, image)
  console.log(`  saved ${path}`)
  // Light and dark are laid out alike, so either measures the marks.
  captured[file] = { marks: await measure(page, file, MARKS[name] ?? {}, device) }
}

/**
 * Write a capture, trying again for a few seconds while the file is locked. On
 * Windows something, a virus scanner or the search index, sometimes holds a
 * file just written, and one failed write would cost the whole run.
 */
async function save(path: string, image: Buffer): Promise<void> {
  for (let attempt = 1; ; attempt++) {
    try {
      writeFileSync(path, image)
      return
    } catch (error) {
      if (attempt === 5) throw error
      await new Promise((resolve) => setTimeout(resolve, 1_000))
    }
  }
}

/**
 * Open a page and wait until it is there. Its heading is enough: on a phone
 * some pages keep it out of sight, so being in the page counts.
 */
async function open(page: Page, path: string): Promise<void> {
  await page.goto(`${BASE_URL}${path}`)
  await page.getByTestId('page-heading').first().waitFor({ state: 'attached', timeout: 20_000 })
}

/** Scroll a part of the page to the middle of the screen, or as near as it goes. */
async function bringIntoView(page: Page, testId: string): Promise<void> {
  await page
    .getByTestId(testId)
    .filter({ visible: true })
    .first()
    .evaluate((node) => node.scrollIntoView({ block: 'center' }))
  await page.waitForTimeout(300)
}

